df = pd.DataFrame(runs)
out = []
for a in sorted(set(df['alpha'])):
    sub = df[df['alpha'] == a]
    out.append({'alpha': a, 'n_ge09': int((sub['drg_overlap'] >= 0.9).sum()), 'mean': round(float(sub['drg_overlap'].mean()), 4), 'std': round(float(sub['drg_overlap'].std()), 4)})
good = [o for o in out if o['n_ge09'] == 5]
chosen = min((o for o in good), key=lambda o: o['alpha'])['alpha'] if good else max(out, key=lambda o: o['mean'])['alpha']
accepted = len(good) > 0
subc = df[df['alpha'] == chosen]
print(json.dumps({'chosen_alpha': chosen, 'accepted': accepted, 'per_alpha': out,
  'drg_mean_chosen': round(float(subc['drg_overlap'].mean()),4), 'drg_std_chosen': round(float(subc['drg_overlap'].std()),4),
  'ari_mean_chosen': round(float(subc['ari'].mean()),4),
  'verdict': ('DRG stably rescued 5/5 at alpha=' + str(chosen)) if accepted else 'DRG NOT stably rescued (no alpha reaches 5/5; report as hard negative, do not claim rescue)'}))
